const seed=()=>{if(get('ready',false))return; const products=names.map((x,i)=>({id:'p'+(i+1),name:x[0],category:x[1],brand:x[2],description:`Premium ${x[0].toLowerCase()} maintained and ready for flexible rental.`,image:pics[i],stock:i===9?0:3+i,availability:i!==9,pricing:{hourly:Math.ceil(x[3]/24),daily:x[3],weekly:x[3]*5,monthly:x[3]*20},securityDeposit:x[4],rating:4+(i%9)/10,colors:i<2?['Charcoal','Blue','Cream']:['Black','Silver'],variants:i===3?['RAM: 16GB','Storage: 512GB','Color: Space Black']:i===7?['Lens: 18-55mm','Color: Black']:['Color: Charcoal']})); const users=[{id:'u1',firstName:'Demo',lastName:'Customer',email:'customer@demo.com',password:'Customer@123',role:'customer',phone:'9876543210',addresses:[{id:'a1',name:'Demo Customer',address:'21 Lake View Road',city:'Bengaluru',state:'Karnataka',country:'India',zip:'560001',phone:'9876543210',default:true}]},{id:'u2',firstName:'Avery',lastName:'Admin',email:'admin@demo.com',password:'Admin@123',role:'admin'},{id:'u3',firstName:'Victor',lastName:'Vendor',email:'vendor@demo.com',password:'Vendor@123',role:'vendor'}]; const order=(id,product,status,start,end)=>({id,userId:'u1',items:[{productId:product.id,name:product.name,image:product.image,quantity:1,price:product.pricing.daily,deposit:product.securityDeposit,variants:['Color: Black']}],rentalStart:start,rentalEnd:end,deliveryMethod:'Delivery',address:users[0].addresses[0],subtotal:product.pricing.daily*3,discount:0,deliveryFee:199,securityDeposit:product.securityDeposit,total:product.pricing.daily*3+199+product.securityDeposit,paymentStatus:'PAID',rentalStatus:status,depositStatus:status==='COMPLETED'?'REFUNDED':'HELD',lateFee:status==='OVERDUE'?300:0,refundAmount:status==='COMPLETED'?product.securityDeposit:0,createdAt:plus(-8)}); const orders=[order('ORD-1001',products[0],'ACTIVE',plus(-2),plus(4)),order('ORD-1002',products[3],'READY_FOR_PICKUP',plus(1),plus(8)),order('ORD-1003',products[7],'OVERDUE',plus(-10),plus(-2)),order('ORD-1004',products[4],'COMPLETED',plus(-15),plus(-8))]; put('products',products);put('users',users);put('orders',orders);put('cart',[]);put('wishlist',[]);put('coupons',[{code:'RENT10',value:10,active:true},{code:'WELCOME20',value:20,active:true}]);put('settings',{company:'RentalFlow',currency:'',lateDaily:100,grace:0});put('ready',true)};
const C=createContext(); const useApp=()=>useContext(C); const money=n=>'Rs. '+Number(n||0).toLocaleString('en-IN');
function Provider({children}){seed();const [user,setUser]=useState(()=>get('user',null)),[products,setProducts]=useState(()=>get('products',[])),[cart,setCart]=useState(()=>get('cart',[])),[orders,setOrders]=useState(()=>get('orders',[])),[wish,setWish]=useState(()=>get('wishlist',[])),[toast,setToast]=useState(null),[theme,setTheme]=useState(()=>get('theme','dark')); useEffect(()=>put('user',user),[user]);useEffect(()=>put('products',products),[products]);useEffect(()=>put('cart',cart),[cart]);useEffect(()=>put('orders',orders),[orders]);useEffect(()=>put('wishlist',wish),[wish]);useEffect(()=>{put('theme',theme);document.documentElement.dataset.theme=theme},[theme]); const flash=(m,type='success')=>{setToast({m,type});setTimeout(()=>setToast(null),2500)}; const login=(email,password)=>{let u=get('users',[]).find(x=>x.email===email&&x.password===password);if(!u)return false;setUser(u);flash('Login successful');return u}; const register=d=>{let users=get('users',[]);if(users.some(x=>x.email===d.email))return false;let u={...d,id:'u'+Date.now(),role:'customer',addresses:[]};put('users',[...users,u]);setUser(u);return true}; const add=(p,config={})=>{if(!p.availability||p.stock<1)return flash('This product is out of stock','error');let start=config.start||plus(1),end=config.end||plus(4),days=Math.max(1,Math.ceil((new Date(end)-new Date(start))/86400000));let item={key:p.id+JSON.stringify(config.variants||[]),productId:p.id,name:p.name,image:p.image,quantity:config.quantity||1,price:p.pricing.daily,deposit:p.securityDeposit,start,end,days,variants:config.variants||[]};setCart(a=>{let old=a.find(x=>x.key===item.key);return old?a.map(x=>x.key===item.key?{...x,quantity:Math.min(x.quantity+1,p.stock)}:x):[...a,item]});flash('Product added to cart')}; const value={user,setUser,products,setProducts,cart,setCart,orders,setOrders,wish,setWish,toast,flash,login,register,add,theme,setTheme};return <C.Provider value={value}>{children}</C.Provider>}
function Protected({admin=false,children}){let {user}=useApp();if(!user)return <Navigate to="/login" replace/>;if(admin&&user.role!=='admin')return <Navigate to="/products" replace/>;return children}
const Status=({s})=><span className={'rounded-full px-2 py-1 text-xs font-bold '+(s.includes('OVERDUE')?'bg-red-500/15 text-red-300':s.includes('COMPLETED')||s.includes('PAID')?'bg-emerald-500/15 text-emerald-300':'bg-indigo-500/15 text-indigo-300')}>{String(s).replaceAll('_',' ')}</span>;
function Shell({children,admin=false}){let {user,cart,wish,setUser,setToken}=useApp(),[open,setOpen]=useState(false),nav=useNavigate();let links=admin?[['Dashboard','/admin/dashboard',LayoutDashboard],['Products','/admin/products',Box],['Rentals','/admin/rentals',CalendarDays],['Orders','/admin/orders',Package],['Customers','/admin/customers',Users],['Pickups','/admin/pickups',CalendarDays],['Returns','/admin/returns',RotateCcw],['Deposits','/admin/deposits',WalletCards],['Coupons','/admin/coupons',Ticket],['Analytics','/admin/analytics',BarChart3],['Settings','/admin/settings',Settings]]:[]; let logout=()=>{setUser(null);setToken('');nav('/login')};return <div className="min-h-screen bg-zinc-950">{admin?<><button className="fixed left-3 top-3 z-30 rounded-lg bg-zinc-800 p-2 lg:hidden" onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button><aside className={(open?'translate-x-0':'-translate-x-full')+' fixed z-20 flex h-full w-64 flex-col border-r border-zinc-800 bg-zinc-950 p-4 transition-transform lg:translate-x-0'}><Link to="/admin/dashboard" className="mb-8 flex items-center gap-2 text-xl font-bold text-white"><span className="rounded-lg bg-brand p-2">R</span>RentalFlow</Link><nav className="space-y-1">{links.map(([n,p,I])=><Link onClick={()=>setOpen(false)} className="flex items-center gap-3 rounded-lg px-3 py-2 text-zinc-400 hover:bg-zinc-800 hover:text-white" to={p} key={p}><I size={18}/>{n}</Link>)}</nav><button onClick={logout} className="btn btn-muted mt-auto"><LogOut size={17}/>Logout</button></aside><main className="lg:ml-64">{children}</main></>:<><header className="sticky top-0 z-20 border-b border-zinc-800 bg-zinc-950/95 backdrop-blur"><div className="mx-auto flex max-w-7xl items-center gap-5 px-4 py-3"><Link to="/products" className="flex items-center gap-2 font-bold"><span className="rounded-lg bg-brand p-2">R</span><span className="hidden sm:inline">RentalFlow</span></Link><nav className="hidden gap-4 text-sm text-zinc-200 md:flex"><Link to="/products">Products</Link><Link to="/about">About Us</Link><Link to="/terms">Terms</Link></nav><SearchBox/><Link className="relative p-2 text-zinc-300" to="/wishlist"><Heart size={20}/>{wish.length>0&&<i className="absolute right-0 top-0 rounded-full bg-brand px-1 text-[10px] not-italic">{wish.length}</i>}</Link><Link className="relative p-2 text-zinc-300" to="/cart"><ShoppingCart size={20}/>{cart.length>0&&<i className="absolute right-0 top-0 rounded-full bg-brand px-1 text-[10px] not-italic">{cart.length}</i>}</Link><Link to="/profile" className="rounded-full bg-zinc-800 p-2"><User size={18}/></Link><ThemeToggle/><button className="hidden text-zinc-400 sm:block" onClick={logout}><LogOut size={18}/></button></div></header>{children}</>}</div>}
function SearchBox(){let [q,setQ]=useState(''),n=useNavigate();return <form className="ml-auto max-w-md flex-1" onSubmit={e=>{e.preventDefault();n('/products?q='+encodeURIComponent(q))}}><input aria-label="Search products" className="field search-field px-4 py-2" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search products..."/></form>}
function Login(){let {login}=useApp(),n=useNavigate(),[form,setForm]=useState({email:'customer@demo.com',password:'Customer@123'}),[err,setErr]=useState(''),[show,setShow]=useState(false);let go=async e=>{e.preventDefault();let u=await login(form.email,form.password);if(!u)return setErr('Invalid email or password.');n(u.role==='admin'?'/admin/dashboard':'/products')};return <div className="grid min-h-screen place-items-center bg-zinc-950 p-4"><form onSubmit={go} className="card w-full max-w-md p-7"><div className="mb-6 text-center"><span className="inline-block rounded-xl bg-brand p-3 text-2xl font-bold">R</span><h1 className="mt-3 text-2xl font-bold">Welcome back</h1><p className="text-sm text-zinc-400">Sign in to RentalFlow</p></div>{err&&<p className="mb-3 rounded-lg bg-red-500/15 p-2 text-sm text-red-300">{err}</p>}<label className="text-sm">Email<input className="field mt-1" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label className="mt-4 block text-sm">Password<div className="relative mt-1"><input type={show?'text':'password'} className="field pr-10" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/><button type="button" onClick={()=>setShow(!show)} className="absolute right-3 top-3 text-zinc-400">{show?<EyeOff size={17}/>:<Eye size={17}/>}</button></div></label><button className="btn btn-primary mt-5 w-full">Log In</button><div className="mt-4 flex justify-between text-sm text-brand"><Link to="/forgot-password">Forgot Password?</Link><Link to="/signup">Register Here</Link><Link to="/vendor/signup">Become a Vendor</Link></div><div className="mt-6 rounded-xl bg-zinc-900 p-3 text-xs text-zinc-400"><b className="text-zinc-200">Demo Accounts</b><br/>Customer: customer@demo.com / Customer@123<br/>Admin: admin@demo.com / Admin@123</div></form></div>}
function Signup(){let {register,flash}=useApp(),n=useNavigate(),[f,setF]=useState({firstName:'',lastName:'',email:'',password:'',confirm:''}),[e,setE]=useState('');let send=async x=>{x.preventDefault();if(!f.firstName||!f.lastName||!/^\S+@\S+\.\S+$/.test(f.email)||f.password.length<6||f.password!==f.confirm)return setE('Enter valid details; passwords must match and be at least 6 characters.');if(!await register(f))return setE('This email is already registered.');flash('Account created');n('/products')};return <div className="grid min-h-screen place-items-center p-4"><form onSubmit={send} className="card w-full max-w-lg p-7"><h1 className="text-2xl font-bold">Create account</h1>{e&&<p className="mt-3 text-sm text-red-300">{e}</p>}<div className="mt-4 grid gap-3 sm:grid-cols-2">{[['firstName','First name'],['lastName','Last name'],['email','Email'],['password','Password'],['confirm','Confirm password']].map(([k,l])=><label className="text-sm" key={k}>{l}<input required type={k.includes('password')||k==='confirm'?'password':k==='email'?'email':'text'} className="field mt-1" value={f[k]} onChange={x=>setF({...f,[k]:x.target.value})}/></label>)}</div><button className="btn btn-primary mt-5 w-full">Create account</button><Link className="mt-4 block text-center text-sm text-brand" to="/login">Already have an account? Login</Link><Link className="mt-2 block text-center text-sm text-brand" to="/vendor/signup">Register as a Vendor</Link></form></div>}
function Forgot(){let n=useNavigate(),[email,setEmail]=useState(''),[msg,setMsg]=useState('');return <div className="grid min-h-screen place-items-center p-4"><form onSubmit={e=>{e.preventDefault();setMsg(get('users',[]).some(u=>u.email===email)?'Password reset link has been sent to your email.':'No account was found for that email.')}} className="card w-full max-w-md p-7"><h1 className="text-xl font-bold">Reset password</h1><p className="my-3 text-sm text-zinc-400">Enter your account email.</p><input type="email" required className="field" value={email} onChange={e=>setEmail(e.target.value)}/><button className="btn btn-primary mt-4 w-full">Send reset link</button>{msg&&<p className="mt-3 text-sm text-emerald-300">{msg}</p>}<button type="button" onClick={()=>n('/login')} className="mt-4 text-sm text-brand">Back to login</button></form></div>}
function Products(){let {products,wish,setWish,add}=useApp(),loc=useLocation(),[brand,setBrand]=useState('All'),[color,setColor]=useState('All'),[max,setMax]=useState(2500);let q=new URLSearchParams(loc.search).get('q')?.toLowerCase()||'';let shown=products.filter(p=>(brand==='All'||p.brand===brand)&&(color==='All'||p.colors?.includes(color)||p.variants?.some(x=>x.includes(color)))&&p.pricing.daily<=max&&JSON.stringify(p).toLowerCase().includes(q));let toggle=p=>setWish(w=>w.some(x=>x.id===p.id)?w.filter(x=>x.id!==p.id):[...w,p]);return <Shell><div className="mx-auto grid max-w-7xl gap-6 p-4 lg:grid-cols-[240px_1fr]"><aside className="card h-fit p-4"><h2 className="font-bold">Filters</h2><label className="mt-4 block text-sm">Brand<select className="field mt-1" value={brand} onChange={e=>setBrand(e.target.value)}><option>All</option>{[...new Set(products.map(p=>p.brand))].map(x=><option key={x}>{x}</option>)}</select></label><label className="mt-4 block text-sm">Color<select className="field mt-1" value={color} onChange={e=>setColor(e.target.value)}><option>All</option>{['Black','Blue','Cream','Silver','Charcoal'].map(x=><option key={x}>{x}</option>)}</select></label><label className="mt-4 block text-sm">Daily price up to {money(max)}<input className="mt-2 w-full accent-brand" type="range" min="400" max="2500" step="100" value={max} onChange={e=>setMax(+e.target.value)}/></label><button className="btn btn-muted mt-4 w-full" onClick={()=>{setBrand('All');setColor('All');setMax(2500)}}>Clear filters</button></aside><section><div className="mb-4 flex items-end justify-between"><div><h1 className="text-2xl font-bold">Rental catalogue</h1><p className="text-sm text-zinc-400">{shown.length} products available</p></div></div>{shown.length?<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{shown.map(p=><article className="card overflow-hidden" key={p.id}><img className="h-44 w-full object-cover" src={p.image} alt={p.name} onError={e=>e.currentTarget.style.display='none'}/><div className="p-4"><div className="flex justify-between gap-2"><h2 className="font-semibold">{p.name}</h2><button aria-label="Toggle wishlist" onClick={()=>toggle(p)} className={wish.some(x=>x.id===p.id)?'text-pink-400':'text-zinc-500'}><Heart size={19} fill={wish.some(x=>x.id===p.id)?'currentColor':'none'}/></button></div><p className="mt-1 text-xs text-zinc-400">{p.brand} | Rating: {p.rating}</p><p className="mt-3 font-bold">{money(p.pricing.daily)} <span className="text-xs font-normal text-zinc-400">/ day</span></p><p className={'mt-1 text-xs '+(p.availability?'text-emerald-400':'text-red-400')}>{p.availability?`${p.stock} available`:'Out of Stock'}</p><div className="mt-3 flex gap-2"><Link className="btn btn-muted flex-1 text-sm" to={'/products/'+p.id}>Details</Link><button disabled={!p.availability} onClick={()=>add(p)} className="btn btn-primary flex-1 text-sm disabled:opacity-40">Add</button></div></div></article>)}</div>:<Empty title="No products found" to="/products" text="Clear your search or filters and try again."/>}</section></div></Shell>}
function Details(){let {id}=useParams(),{products,add}=useApp(),p=products.find(x=>x.id===id),n=useNavigate(),[f,setF]=useState({start:plus(1),end:plus(4),quantity:1,variants:[]}),[e,setE]=useState('');if(!p)return <Shell><Empty title="Product Not Found" to="/products"/></Shell>;let days=Math.max(1,Math.ceil((new Date(f.end)-new Date(f.start))/86400000));let send=(go=false)=>{if(new Date(f.end)<=new Date(f.start))return setE('End date must be after start date.');if(p.variants.length&&!f.variants.length)return setE('Select a product option.');add(p,f);if(go)n('/cart')};return <Shell><div className="mx-auto grid max-w-5xl gap-8 p-5 md:grid-cols-2"><img className="card h-80 w-full object-cover" src={p.image} alt={p.name}/><section><Link to="/products" className="text-sm text-brand"> Back to products</Link><h1 className="mt-3 text-3xl font-bold">{p.name}</h1><p className="mt-2 text-zinc-400">Rating: {p.rating} | {p.brand}</p><p className="mt-5 text-2xl font-bold">{money(p.pricing.daily)} <span className="text-sm font-normal text-zinc-400">/ day</span></p><p className="mt-2 text-zinc-400">Security deposit: <b className="text-white">{money(p.securityDeposit)}</b></p><p className="mt-4 text-sm text-zinc-300">{p.description}</p><div className="mt-5 grid gap-3 sm:grid-cols-2"><label className="text-sm">Start date<input type="date" min={plus(0)} className="field mt-1" value={f.start} onChange={x=>setF({...f,start:x.target.value})}/></label><label className="text-sm">End date<input type="date" min={f.start} className="field mt-1" value={f.end} onChange={x=>setF({...f,end:x.target.value})}/></label></div>{p.variants.length>0&&<label className="mt-4 block text-sm">Choose variant<select className="field mt-1" value={f.variants[0]||''} onChange={x=>setF({...f,variants:[x.target.value]})}><option value="">Select an option</option>{p.variants.map(x=><option key={x}>{x}</option>)}</select></label>}<label className="mt-4 block text-sm">Quantity<input min="1" max={p.stock} type="number" className="field mt-1" value={f.quantity} onChange={x=>setF({...f,quantity:+x.target.value})}/></label>{e&&<p className="mt-3 text-sm text-red-300">{e}</p>}<p className="mt-4 text-sm text-zinc-400">{days} rental day(s) | Estimated rental {money(days*p.pricing.daily*f.quantity)}</p><div className="mt-5 flex gap-3"><button className="btn btn-primary" disabled={!p.availability} onClick={()=>send()}>Add to cart</button><button className="btn btn-muted" disabled={!p.availability} onClick={()=>send(true)}>Rent now</button></div></section></div></Shell>}
function Cart(){let {cart,setCart,products,add}=useApp(),n=useNavigate(),[code,setCode]=useState(''),[discount,setDiscount]=useState(0),[msg,setMsg]=useState('');let sub=cart.reduce((s,x)=>s+x.price*x.days*x.quantity,0),dep=cart.reduce((s,x)=>s+x.deposit*x.quantity,0),delivery=cart.length?199:0,total=sub+dep+delivery-discount;let coupon=()=>{let c=get('coupons',[]).find(x=>x.code===code.toUpperCase()&&x.active);if(!c)return setMsg('Invalid coupon');setDiscount(Math.round(sub*c.value/100));setMsg(`${c.value}% discount applied`)};if(!cart.length)return <Shell><div className="mx-auto max-w-3xl p-6"><Empty title="Your cart is empty" text="Find your next rental in our catalogue." to="/products"/></div></Shell>;return <Shell><div className="mx-auto grid max-w-6xl gap-6 p-5 lg:grid-cols-[1fr_350px]"><section><h1 className="mb-4 text-2xl font-bold">Your cart</h1>{cart.map(x=><div className="card mb-3 flex gap-3 p-3" key={x.key}><img className="h-24 w-24 rounded-lg object-cover" src={x.image} alt=""/><div className="min-w-0 flex-1"><h2 className="font-semibold">{x.name}</h2><p className="text-xs text-zinc-400">{x.variants.join(', ')||'Standard'}  {x.start} to {x.end}</p><p className="mt-2 text-sm">{money(x.price)}  {x.days} days</p><div className="mt-2 flex items-center gap-2"><button className="rounded bg-zinc-800 p-1" onClick={()=>setCart(a=>a.map(i=>i.key===x.key?{...i,quantity:Math.max(1,i.quantity-1)}:i))}><Minus size={15}/></button><b>{x.quantity}</b><button className="rounded bg-zinc-800 p-1" onClick={()=>setCart(a=>a.map(i=>i.key===x.key?{...i,quantity:Math.min(products.find(p=>p.id===x.productId).stock,i.quantity+1)}:i))}><Plus size={15}/></button><button className="ml-auto text-red-300" onClick={()=>setCart(a=>a.filter(i=>i.key!==x.key))}><Trash2 size={18}/></button></div></div></div>)}<button className="btn btn-muted" onClick={()=>n('/products')}><ArrowLeft size={16}/>Continue shopping</button></section><aside className="card h-fit p-5"><h2 className="font-bold">Order summary</h2><div className="mt-4 space-y-2 text-sm text-zinc-400"><p className="flex justify-between"><span>Rental subtotal</span><b className="text-white">{money(sub)}</b></p><p className="flex justify-between"><span>Delivery</span><b className="text-white">{money(delivery)}</b></p><p className="flex justify-between"><span>Security deposit</span><b className="text-amber-300">{money(dep)}</b></p><p className="flex justify-between"><span>Discount</span><b className="text-emerald-300">{money(discount)}</b></p></div><div className="mt-4 flex gap-2"><input className="field" placeholder="Coupon code" value={code} onChange={e=>setCode(e.target.value)}/><button className="btn btn-muted" onClick={coupon}>Apply</button></div>{msg&&<p className={'mt-2 text-xs '+(discount?'text-emerald-300':'text-red-300')}>{msg}</p>}<p className="mt-5 flex justify-between border-t border-zinc-700 pt-4 text-lg font-bold"><span>Total</span>{money(total)}</p><button className="btn btn-primary mt-4 w-full" onClick={()=>n('/checkout/address',{state:{discount}})}>Checkout <ChevronRight size={17}/></button></aside></div></Shell>}
function Address(){let {user,setUser}=useApp(),n=useNavigate(),loc=useLocation(),[method,setMethod]=useState('Delivery'),[addr,setAddr]=useState(user.addresses?.[0]||{}),[newAddr,setNewAddr]=useState(false);let next=e=>{e.preventDefault();if(method==='Delivery'&&(!addr.address||!addr.city))return;let users=get('users',[]).map(u=>u.id===user.id?{...u,addresses:[{...addr,id:addr.id||'a'+Date.now(),default:true}]}:u);put('users',users);let updated=users.find(u=>u.id===user.id);setUser(updated);n('/checkout/payment',{state:{...loc.state,method,address:addr}})};return <Shell><form onSubmit={next} className="mx-auto max-w-3xl p-6"><h1 className="text-2xl font-bold">Delivery or pickup</h1><div className="mt-5 grid gap-3 sm:grid-cols-2">{['Delivery','Store Pickup'].map(x=><button type="button" key={x} onClick={()=>setMethod(x)} className={'card p-4 text-left '+(method===x?'border-brand':'')}><b>{x}</b><p className="mt-1 text-sm text-zinc-400">{x==='Delivery'?'Delivered to your saved address.':'RentalFlow Store, Indiranagar, Bengaluru.'}</p></button>)}</div>{method==='Delivery'&&<div className="card mt-5 p-5"><div className="flex justify-between"><h2 className="font-semibold">Delivery address</h2><button type="button" className="text-sm text-brand" onClick={()=>setNewAddr(!newAddr)}>{newAddr?'Use saved':'Add/edit address'}</button></div>{!newAddr&&addr.address?<p className="mt-3 text-sm text-zinc-300">{addr.name}<br/>{addr.address}, {addr.city}, {addr.state} {addr.zip}</p>:<div className="mt-3 grid gap-3 sm:grid-cols-2">{[['name','Full name'],['address','Address'],['city','City'],['state','State'],['zip','ZIP'],['phone','Phone']].map(([k,l])=><input key={k} required className="field" placeholder={l} value={addr[k]||''} onChange={e=>setAddr({...addr,[k]:e.target.value})}/>)}</div>}</div>}<div className="card mt-5 p-5"><h2 className="font-semibold">Billing address</h2><label className="mt-3 flex gap-2 text-sm text-zinc-300"><input type="checkbox" defaultChecked/> Billing address is same as delivery address</label></div><button className="btn btn-primary mt-5">Continue to payment <ChevronRight size={17}/></button></form></Shell>}
function Payment(){let {cart,setCart,orders,setOrders,user,flash}=useApp(),n=useNavigate(),loc=useLocation(),[f,setF]=useState({card:'4111111111111111',name:`${user.firstName} ${user.lastName}`,expiry:'12/28',cvv:'123'}),[loading,setLoading]=useState(false),[err,setErr]=useState('');let sub=cart.reduce((s,x)=>s+x.price*x.days*x.quantity,0),dep=cart.reduce((s,x)=>s+x.deposit*x.quantity,0),dis=loc.state?.discount||0,total=sub+dep+199-dis;let pay=e=>{e.preventDefault();if(f.card.replaceAll(' ','').length<12||f.cvv.length<3)return setErr('Enter valid mock card details.');setLoading(true);setTimeout(()=>{let o={id:'ORD-'+Math.floor(100000+Math.random()*899999),userId:user.id,items:cart,rentalStart:cart[0]?.start,rentalEnd:cart[0]?.end,deliveryMethod:loc.state?.method||'Delivery',address:loc.state?.address||{},subtotal:sub,discount:dis,deliveryFee:199,securityDeposit:dep,total,paymentStatus:'PAID',rentalStatus:'CONFIRMED',depositStatus:'HELD',lateFee:0,refundAmount:0,createdAt:iso(today),invoice:'INV-'+Date.now()};setOrders([o,...orders]);setCart([]);flash('Order placed successfully');n('/checkout/success',{state:{order:o}})},900)};return <Shell><div className="mx-auto grid max-w-5xl gap-5 p-6 md:grid-cols-[1fr_360px]"><form onSubmit={pay} className="card p-5"><h1 className="text-2xl font-bold">Payment details</h1><p className="mt-2 text-sm text-zinc-400">This is a secure simulated payment.</p>{[['card','Card number'],['name','Cardholder name'],['expiry','Expiry (MM/YY)'],['cvv','CVV']].map(([k,l])=><label className="mt-4 block text-sm" key={k}>{l}<input className="field mt-1" value={f[k]} onChange={e=>setF({...f,[k]:e.target.value})}/></label>)}{err&&<p className="mt-3 text-sm text-red-300">{err}</p>}<button disabled={loading||!cart.length} className="btn btn-primary mt-5 w-full">{loading?'Processing payment':`Pay ${money(total)}`}</button></form><aside className="card h-fit p-5"><h2 className="font-bold">Order review</h2>{cart.map(x=><p className="mt-3 text-sm text-zinc-400" key={x.key}>{x.name}  {x.quantity}<b className="float-right text-white">{money(x.price*x.days*x.quantity)}</b></p>)}<div className="mt-4 space-y-2 border-t border-zinc-700 pt-4 text-sm"><p>Rental <b className="float-right">{money(sub)}</b></p><p>Delivery <b className="float-right">199</b></p><p className="text-amber-300">Security deposit <b className="float-right">{money(dep)}</b></p><p>Discount <b className="float-right">{money(dis)}</b></p><p className="border-t border-zinc-700 pt-3 text-lg font-bold">Total <b className="float-right">{money(total)}</b></p></div></aside></div></Shell>}
function Success(){let {state}=useLocation(),n=useNavigate(),o=state?.order;if(!o)return <Navigate to="/orders"/>;return <Shell><div className="mx-auto max-w-2xl p-8 text-center"><CheckCircle2 className="mx-auto text-emerald-400" size={68}/><h1 className="mt-4 text-3xl font-bold">Thank you for your order</h1><p className="mt-2 text-zinc-400">Your payment has been processed. Order #{o.id}</p><div className="card mt-6 p-5 text-left"><p>Rental period <b className="float-right">{o.rentalStart} to {o.rentalEnd}</b></p><p className="mt-3">Security deposit <b className="float-right text-amber-300">{money(o.securityDeposit)} held</b></p><p className="mt-3">Total paid <b className="float-right">{money(o.total)}</b></p></div><div className="mt-5 flex justify-center gap-3"><button className="btn btn-muted" onClick={()=>window.print()}><Download size={16}/>Invoice</button><button className="btn btn-primary" onClick={()=>n('/orders/'+o.id)}>View order</button></div></div></Shell>}
function Orders(){let {orders,user}=useApp(),[tab,setTab]=useState('All'),mine=orders.filter(o=>o.userId===user.id).filter(o=>tab==='All'||(tab==='Active'?['ACTIVE','OVERDUE','PICKED_UP'].includes(o.rentalStatus):tab==='Upcoming'?['CONFIRMED','READY_FOR_PICKUP'].includes(o.rentalStatus):o.rentalStatus==='COMPLETED'));return <Shell><div className="mx-auto max-w-6xl p-5"><h1 className="text-2xl font-bold">My rentals</h1><div className="mt-4 flex gap-2 overflow-auto">{['All','Active','Upcoming','Completed'].map(t=><button key={t} onClick={()=>setTab(t)} className={'btn text-sm '+(tab===t?'btn-primary':'btn-muted')}>{t}</button>)}</div><div className="mt-5 space-y-3">{mine.map(o=><Link className="card block p-4 hover:border-zinc-600" to={'/orders/'+o.id} key={o.id}><b>{o.id}</b><Status s={o.rentalStatus}/><p className="mt-2 text-sm text-zinc-400">{o.items.map(i=>i.name).join(', ')}  {o.rentalStart} to {o.rentalEnd}<span className="float-right text-white">{money(o.total)}</span></p></Link>)}{!mine.length&&<Empty title="No rentals yet" to="/products"/>}</div></div></Shell>}
