function Wishlist(){let {wish,setWish,add}=useApp();return <Shell><div className="mx-auto max-w-6xl p-5"><h1 className="text-2xl font-bold">Wishlist</h1>{wish.length?<div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{wish.map(p=><div className="card p-4" key={p.id}><img className="h-36 w-full rounded-lg object-cover" src={p.image} alt=""/><h2 className="mt-3 font-semibold">{p.name}</h2><div className="mt-3 flex gap-2"><button className="btn btn-primary flex-1" onClick={()=>add(p)}>Move to cart</button><button className="btn btn-muted" onClick={()=>setWish(w=>w.filter(x=>x.id!==p.id))}><Trash2 size={17}/></button></div></div>)}</div>:<Empty title="Your wishlist is empty" to="/products"/>}</div></Shell>}
